-- rebuild-carnet 015 + 048 + 050 + 059 + 067 + 068 + 071 + 090 + 091 + 097 (2026-09-29): remap reader reports to the new paragraph IDs.
-- paragraph_reports is the only table keyed by paragraph ID (src/auth/init.sql).
-- Reading history / bookmarks live in each reader's localStorage and cannot be remapped here.
-- One UPDATE through a mapping table, so a chain like 0005→0006→0007 cannot double-apply.
BEGIN;
CREATE TEMP TABLE renumber_015_048_050_059_067_068_071_090_091_097 (old_id TEXT PRIMARY KEY, new_id TEXT NOT NULL) ON COMMIT DROP;
UPDATE paragraph_reports r SET paragraph_id = m.new_id FROM renumber_015_048_050_059_067_068_071_090_091_097 m WHERE r.paragraph_id = m.old_id;
COMMIT;
